      <button type="button" data-testid="plan-amount-save" disabled={save.isPending}
        onClick={() => {
          const value = amount;
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(value);
          });
        }}>
        Save amount
      </button>
      {save.isError && (
        <span data-testid="plan-error">A plan's amount is 0.00 or more with up to two decimals.</span>
      )}
    </td>
  );
}
"""
